import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as usageService from "@/server/services/usage-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { OrgId } from "@/types/common";

function input(orgId: OrgId, o: Partial<{ name: string; slug: string; key: string }> = {}): CreateProjectInput {
  return {
    orgId,
    name: o.name ?? "Widget Works",
    slug: o.slug ?? "widget-works",
    key: o.key ?? "WID",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

let cleanup: () => void;
let offUsage: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offUsage = registerUsageListeners();
});
afterAll(() => {
  offUsage();
  cleanup();
});

describe("scratch verification", () => {
  it("1. archiving frees a Free-plan slot; restore is refused when full", async () => {
    const t = await createTenant("scr1", "free"); // 1 live project (platform)
    const second = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Second", slug: "second", key: "SEC" }));
    // 2 live now -> full
    await expect(projectService.createProject(t.actors.member, input(t.org.id, { name: "Third", slug: "third", key: "THI" }))).rejects.toThrow(/allows 2 projects/);

    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: second.id, archiveIssues: true });
    // slot freed -> create works
    const third = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Third", slug: "third", key: "THI" }));
    expect(third.id).toBeDefined();
    expect((await usageService.getUsage(t.actors.member, t.org.id)).projectsUsed).toBe(2);

    // full again (platform + third) -> restoring second refused, nothing changes
    const received: unknown[] = [];
    const off = subscribe("project.restored", (p) => { received.push(p); });
    await expect(projectService.restoreProject(t.actors.admin, t.org.id, second.id)).rejects.toThrow(/allows 2 projects/);
    off();
    expect(received).toHaveLength(0);
    expect((await projectRepo.findProjectById(t.org.id, second.id))?.archivedAt).not.toBeNull();
    expect((await usageService.getUsage(t.actors.member, t.org.id)).projectsUsed).toBe(2);
    expect(await projectRepo.countProjects(t.org.id)).toBe(2);
  });

  it("2. look-alike names get a unique key, archived keys included", async () => {
    const t = await createTenant("scr2", "growth");
    const a = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Web Visitors", slug: "web-visitors", key: "WV" }));
    expect(a.key).toBe("WV");
    const b = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Web Vendors", slug: "web-vendors", key: "WV" }));
    expect(b.key).toBe("WV2");
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: b.id, archiveIssues: false });
    const c = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Web Vault", slug: "web-vault", key: "WV" }));
    expect(c.key).toBe("WV3");
    // four-char key trims base
    const d = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Abcd", slug: "abcd", key: "ABCD" }));
    const e = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Abcd2", slug: "abcd2", key: "ABCD" }));
    expect(d.key).toBe("ABCD");
    expect(e.key).toBe("ABC2");
    // a different org can use WV
    const other = await createTenant("scr2b", "growth");
    const f = await projectService.createProject(other.actors.member, input(other.org.id, { name: "Web Other", slug: "web-other", key: "WV" }));
    expect(f.key).toBe("WV");
  });

  it("3. archived address stays reserved; restore still works", async () => {
    const t = await createTenant("scr3", "growth"); // seeded "platform"
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, archiveIssues: false });
    const fresh = await projectService.createProject(t.actors.member, input(t.org.id, { name: "Platform", slug: "platform", key: "PLX" }));
    expect(fresh.slug).toBe("platform-2");
    await expect(projectService.suggestProjectSlug(t.org.id, "Platform")).resolves.toBe("platform-3");
    const restored = await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect(restored.slug).toBe("platform");
    expect(restored.archivedAt).toBeNull();
  });

  it("4. restore meters a project back; recount agrees", async () => {
    const t = await createTenant("scr4", "growth");
    await usageService.recomputeUsage(t.org.id);
    const before = (await usageService.getUsage(t.actors.member, t.org.id)).projectsUsed;
    expect(before).toBe(1);
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    expect((await usageService.getUsage(t.actors.member, t.org.id)).projectsUsed).toBe(0);
    await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect((await usageService.getUsage(t.actors.member, t.org.id)).projectsUsed).toBe(1);
    const recount = await usageService.recomputeUsage(t.org.id);
    expect(recount.projectsUsed).toBe(1);
  });

  it("5. restoring a live project is refused and announces nothing", async () => {
    const t = await createTenant("scr5", "growth");
    const received: unknown[] = [];
    const off = subscribe("project.restored", (p) => { received.push(p); });
    await expect(projectService.restoreProject(t.actors.admin, t.org.id, t.project.id)).rejects.toThrow(/not archived/);
    off();
    expect(received).toHaveLength(0);
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.archivedAt).toBeNull();
  });

  it("6. status persists; completion guard; paused blocks issues; archived status frozen", async () => {
    const t = await createTenant("scr6", "growth");
    const paused = await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "paused" });
    expect(paused.status).toBe("paused");
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.status).toBe("paused");
    expect((await projectRepo.listProjects({ orgId: t.org.id, limit: 100, cursor: null, status: "paused" } as never)).items.map((p) => p.id)).toContain(t.project.id);

    // paused refuses new issues, nothing created, nothing announced
    const created: unknown[] = [];
    const off = subscribe("issue.created", (p) => { created.push(p); });
    await expect(issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "x" }))).rejects.toThrow(/paused/);
    off();
    expect(created).toHaveLength(0);
    expect(await issueRepo.countIssues(t.org.id, t.project.id, { includeArchived: true })).toBe(0);

    // reactivate, add 3 issues (more than a page), one open -> completion refused
    await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "active" });
    const issues = [];
    for (let i = 0; i < 3; i += 1) {
      issues.push(await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: `i${i}` })));
    }
    await expect(projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "completed" })).rejects.toThrow(/open issue/);
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.status).toBe("active");

    // close all: done, canceled, and an archived open one -> allowed
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issues[0]!.id, status: "done" });
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issues[1]!.id, status: "canceled" });
    await issueService.archiveIssue(t.actors.admin, t.org.id, issues[2]!.id);
    const done = await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "completed" });
    expect(done.status).toBe("completed");
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.status).toBe("completed");

    // completed again: no change
    const again = await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "completed" });
    expect(again.status).toBe("completed");

    // existing issues still workable in completed project
    const moved = await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issues[0]!.id, status: "in_progress" });
    expect(moved.status).toBe("in_progress");

    // completed refuses new issues
    await expect(issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "late" }))).rejects.toThrow(/completed/);

    // reactivating and pausing always possible
    await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "paused" });
    await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "active" });

    // archived project status cannot change
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, archiveIssues: false });
    await expect(projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "paused" })).rejects.toThrow();
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.status).toBe("active");
  });

  it("7. restore keeps the status and archived issues archived", async () => {
    const t = await createTenant("scr7", "growth");
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "a" }));
    await projectService.updateProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, status: "paused" });
    await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    const restored = await projectService.restoreProject(t.actors.admin, t.org.id, t.project.id);
    expect(restored.status).toBe("paused");
    expect(restored.archivedAt).toBeNull();
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(0);
    expect(issue.id).toBeDefined();
  });
});

